class Solution {
  public int longestLine(int[][] mat) {
    int m = mat.length, n = mat[0].length, best = 0;
    int[][][] dp = new int[m + 1][n + 2][4]; // horizontal, vertical, diagonal, anti-diagonal
    for (int i = 1; i <= m; i++)
      for (int j = 1; j <= n; j++) {
        if (mat[i - 1][j - 1] == 0) continue;
        dp[i][j][0] = dp[i][j - 1][0] + 1;
        dp[i][j][1] = dp[i - 1][j][1] + 1;
        dp[i][j][2] = dp[i - 1][j - 1][2] + 1;
        dp[i][j][3] = dp[i - 1][j + 1][3] + 1;
        for (int d = 0; d < 4; d++) best = Math.max(best, dp[i][j][d]);
      }
    return best;
  }
}
